// Shapes of the data in public/data/world.json, generated by scripts/build_world_data.py.
// Keep these in sync with the Python script's output.

export type City = {
  id: number;
  name: string;
  lat: number;
  lng: number;
  population: number;
};

export type Country = {
  code: string;      // ISO alpha-2, e.g. "KR" (used for flags later)
  iso3: string;      // "KOR"
  numeric: string;   // "410" (matches the map shapes' ids)
  name: string;
  continent: string;
  capital: string;
  population: number;
  cities: City[];
};

export type World = {
  source: string;
  generatedAt: string;
  maxCitiesPerCountry: number;
  countries: Country[];
};
